def subtract(a, b):
    # Filter out empty intervals and collect all intervals
    a_intervals = [interval for interval in a if interval[0] < interval[1]]
    b_intervals = [interval for interval in b if interval[0] < interval[1]]

    if not a_intervals:
        return []

    if not b_intervals:
        return sorted(a_intervals)

    # Merge overlapping intervals in a
    a_sorted = sorted(a_intervals)
    a_merged = []
    for start, end in a_sorted:
        if a_merged and a_merged[-1][1] >= start:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Merge overlapping intervals in b
    b_sorted = sorted(b_intervals)
    b_merged = []
    for start, end in b_sorted:
        if b_merged and b_merged[-1][1] >= start:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_intervals = []
            for curr_start, curr_end in current_intervals:
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap
                    new_intervals.append([curr_start, curr_end])
                else:
                    # There is overlap, split the interval
                    if curr_start < b_start:
                        new_intervals.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_intervals.append([b_end, curr_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    # Merge touching intervals in result
    if not result:
        return []

    result_sorted = sorted(result)
    merged_result = []
    for start, end in result_sorted:
        if merged_result and merged_result[-1][1] >= start:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

